+function makeIO() {
+  const stdout = [];
+  const stderr = [];
+  return {
+    io: {
+      log: (...args) => stdout.push(args.join(' ')),
+      err: (...args) => stderr.push(args.join(' ')),
+    },
+    stdout,
+    stderr,
+  };
+}
+
+test('convert i18next JSON to .lino', async () => {
