+  assert.match(enText, /^en/);
+  assert.match(enText, /greeting ['"]Hello, \{\{name\}\}['"]/);
+  assert.match(enText, /cart\.items_one ['"]\{\{count\}\} item['"]/);
+  assert.match(enText, /cart\.items_other ['"]\{\{count\}\} items['"]/);
