-export function parseVersion(version) {
-  const match = String(version)
-    .trim()
-    .match(
-      /^v?(\d+)\.(\d+)\.(\d+)(?:-([0-9A-Za-z-.]+))?(?:\+[0-9A-Za-z-.]+)?$/
-    );
